import csv, struct
from pathlib import Path
import json
inventory = json.loads(Path("docs/preset-evidence/2026.11.4/baseline/inventory.json").read_text())
rows = list(csv.DictReader(Path("docs/preset-evidence/2026.11.4/baseline/single-note-metrics.csv").open()))
def digest(values):
    h = 14695981039346656037
    for value in values:
        for byte in struct.pack("<f", value):
            h = ((h ^ byte) * 1099511628211) % (1 << 64)
    return format(h, "x")
assert len(rows) == len(inventory["programs"]) == 523
for row, program in zip(rows, inventory["programs"]):
    assert int(row["index"]) == program["index"] == program["host_index"]
    assert (row["name"], row["category"]) == (program["name"], program["category"])
    assert row["parameter_digest"] == digest(program["values"])
